// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 100 ether);
        // install a fully functional log via the public SetLogFile entry
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        // with a working log installed, ANY deposit must succeed
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
